def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.156.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.155.0"' not in init:
        sys.exit("ABORT: not at v3.155.0.")
    for k in ("concessions_returns", "extended_counters"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("POS5", LESSONS_M5, QUESTIONS_M5, 9) + _validate("POS6", LESSONS_M6, QUESTIONS_M6, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("POS 5", LESSONS_M5, QUESTIONS_M5, "concessions_returns",
         "Discounts and returns as controlled exceptions: the five parts of every exception, the three discount modes at the till, markdown reasons with budget percentages, the discount request cycle through category leads, promotions that lock the line and bundles retired by deactivation, rate edits and credit releases under the approval mechanics, and the Return & Exchange console's three steps with loyalty recovery."),
        ("POS 6", LESSONS_M6, QUESTIONS_M6, "extended_counters",
         "The extended counters as financial arrangements: creating and managing lay-bys through completion or manager-gated termination, staff purchases with the payroll recovery chain proven end to end, airtime under the consumed-on-issue rule with reprint-by-invoice, Sales History and the Customer Desk with the reversible monthly merge, and Inventory Ops with prioritised requests, confirmed-quantity receiving, offline label printing and the Message Hub."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v2: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.155.0"', '"3.156.0"'))
    print("  data: POS 5 + POS 6 lessons + banks REPLACED (style v2.1)")
    print("wrote __version__ -> 3.156.0")


if __name__ == "__main__":
    main()
